-- M3-02 SQLite schema v1. Financial values are tagged decimal strings in payload.
CREATE TABLE schema_version(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL) STRICT;
CREATE TABLE meta(key TEXT PRIMARY KEY, value TEXT NOT NULL) STRICT;
CREATE TABLE uow_commits(txn_id TEXT PRIMARY KEY, account_id TEXT NOT NULL, committed_at INTEGER NOT NULL) STRICT;
CREATE TABLE orders(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX orders_working ON orders(account_id,active,updated_at);
CREATE TABLE fills(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX fills_working ON fills(account_id,active,updated_at);
CREATE TABLE order_events(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX order_events_working ON order_events(account_id,active,updated_at);
CREATE TABLE positions(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX positions_working ON positions(account_id,active,updated_at);
CREATE TABLE decisions(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX decisions_working ON decisions(account_id,active,updated_at);
CREATE TABLE episodes(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), strategy TEXT, symbol TEXT, closed_at INTEGER, PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX episodes_working ON episodes(account_id,active,updated_at);
CREATE TABLE books(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX books_working ON books(account_id,active,updated_at);
CREATE TABLE close_intents(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX close_intents_working ON close_intents(account_id,active,updated_at);
CREATE TABLE portfolio_actions(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_actions_working ON portfolio_actions(account_id,active,updated_at);
CREATE TABLE portfolio_action_keys(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_action_keys_working ON portfolio_action_keys(account_id,active,updated_at);
CREATE TABLE portfolio_paused(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_paused_working ON portfolio_paused(account_id,active,updated_at);
CREATE TABLE funding_applied(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX funding_applied_working ON funding_applied(account_id,active,updated_at);
CREATE TABLE portfolio_symbol_state(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_symbol_state_working ON portfolio_symbol_state(account_id,active,updated_at);
CREATE TABLE portfolio_stop_times(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_stop_times_working ON portfolio_stop_times(account_id,active,updated_at);
CREATE TABLE portfolio_pause_revisions(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_pause_revisions_working ON portfolio_pause_revisions(account_id,active,updated_at);
CREATE TABLE protection_recoveries(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX protection_recoveries_working ON protection_recoveries(account_id,active,updated_at);
CREATE TABLE portfolio_fill_times(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX portfolio_fill_times_working ON portfolio_fill_times(account_id,active,updated_at);
CREATE TABLE recovery_active(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX recovery_active_working ON recovery_active(account_id,active,updated_at);
CREATE TABLE recovery_archive(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), updated_at INTEGER NOT NULL, active INTEGER NOT NULL CHECK(active IN (0,1)), PRIMARY KEY(account_id,key)) STRICT;
CREATE INDEX recovery_archive_working ON recovery_archive(account_id,active,updated_at);
CREATE UNIQUE INDEX one_active_episode ON episodes(account_id,strategy,symbol) WHERE closed_at IS NULL;
CREATE TABLE risk_states(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE equity_snapshots(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE cash_flows(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE alerts(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE config_versions(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE boundary_inputs(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE boundary_outputs(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE boundary_checkpoints(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE position_snapshots(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE unallocated_funding(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE bars(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE market_snapshots(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE news_items(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE ai_calls(account_id TEXT NOT NULL, key TEXT NOT NULL, payload TEXT NOT NULL CHECK(json_valid(payload)), created_at INTEGER NOT NULL, PRIMARY KEY(account_id,key)) STRICT;
CREATE TABLE protective_operations(account_id TEXT NOT NULL, operation_id TEXT NOT NULL, phase TEXT NOT NULL, group_id TEXT, step TEXT, attempt INTEGER, action_key TEXT, payload TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(account_id,operation_id,phase)) STRICT;
CREATE TABLE commands(account_id TEXT NOT NULL, request_id TEXT NOT NULL, source TEXT NOT NULL CHECK(source IN ('telegram','web')), state TEXT NOT NULL, payload TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(account_id,request_id)) STRICT;
CREATE TABLE command_targets(account_id TEXT NOT NULL, request_id TEXT NOT NULL, order_key TEXT NOT NULL, state TEXT NOT NULL, attempts INTEGER NOT NULL, payload TEXT NOT NULL, PRIMARY KEY(account_id,request_id,order_key), FOREIGN KEY(account_id,request_id) REFERENCES commands(account_id,request_id)) STRICT;
